export type PoseGender = 'female' | 'male';
export const POSE_CARD_LABEL = '姿势示意·待审核';
export const POSE_CARD_IDS: readonly string[] = Object.keys(FILES);
export function poseCardUrl(exerciseId: string | null | undefined, gender: PoseGender): string | null {
  const file = exerciseId ? FILES[exerciseId] : undefined;
  return file ? `/fangkun-pose-r8/${gender}/${file}` : null;
}
import { loadProfile } from './profile';
/** 用户资料里的性别；未填写时默认女版（界面保留男/女切换）。 */
export function defaultPoseGender(): PoseGender {
  try { const sex = loadProfile().sex; return sex === 'male' ? 'male' : 'female'; } catch { return 'female'; }
}

