export interface PoseFrame { key: PoseFrameKey; label: string; url: string | null }
/** 返回固定三帧；缺的帧 url 为 null，由页面提示“缺：xx”。 */
export function poseFrames(exerciseId: string | null | undefined, gender: PoseGender): PoseFrame[] {
  const file = exerciseId ? FILES[exerciseId] : undefined;
  const have = exerciseId ? FRAME_PRESENT[exerciseId]?.[gender] ?? '' : '';
  return FRAME_ORDER.map(key => ({ key, label: POSE_FRAME_LABEL[key], url: file && have.includes(key[0]) ? `/fangkun-pose-r8/${gender}/${file.replace(/\.webp$/, '')}--${key}.webp` : null }));
}
